import os
import google.generativeai as genai

def moderate_batch(payload, config=None):
    config = config or {}
    genai.configure(api_key=os.environ["GEMINI_API_KEY"])
    client = genai.GenerativeModel("gemini-1.5-flash")

    # Gemini's content moderation is built-in with generation, 
    # but for explicit safety checks without generating text,
    # we can try to "generate" with the safety settings and see if it's blocked.
    # Alternatively, one might use a dedicated content safety API like Google Cloud's Text Moderation.
    # For this task, we will demonstrate using Gemini's built-in safety features and then
    # manually interpreting "blocked" vs "allowed" based on the response.

    # Note: A dedicated content safety API might provide more granular category scores.
    # This approach primarily checks if the content would be blocked by Gemini's default safety settings.

    safety_settings = [
        {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
        {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
        {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
        {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
    ]

    results = []
    for message in payload:
        try:
            response = client.generate_content(
                message,
                safety_settings=safety_settings,
                # Explicitly setting a low temperature and max_output_tokens 
                # to minimize actual generation when we just want safety check.
                # However, the primary signal for safety here is if generation is blocked.
                generation_config={"temperature": 0.0, "max_output_tokens": 1} 
            )
            # If the generation is not blocked, it's considered "safe" by Gemini's standards for generation.
            # We don't care about the generated content itself, just the fact that it *could* generate.
            is_safe = True
            safety_ratings_info = []
            if hasattr(response, 'prompt_feedback') and response.prompt_feedback.safety_ratings:
                for rating in response.prompt_feedback.safety_ratings:
                    safety_ratings_info.append({
                        "category": rating.category.name,
                        "threshold": rating.threshold.name,
                        "blocked": rating.blocked,
                        "severity": rating.severity.name if hasattr(rating, 'severity') else 'UNKNOWN'
                    })

            results.append({
                "message": message,
                "is_safe": is_safe,
                "details": {"safety_ratings": safety_ratings_info}
            })

        except Exception as e:
            # If an exception occurs, especially a BlockedPromptException, it means the content was unsafe.
            is_safe = False
            error_details = str(e)
            safety_ratings_info = []

            # Attempt to parse specific block reasons from the exception if available
            if hasattr(e, 'response') and hasattr(e.response, 'prompt_feedback'):
                 for rating in e.response.prompt_feedback.safety_ratings:
                    safety_ratings_info.append({
                        "category": rating.category.name,
                        "threshold": rating.threshold.name,
                        "blocked": rating.blocked,
                        "severity": rating.severity.name if hasattr(rating, 'severity') else 'UNKNOWN'
                    })

            results.append({
                "message": message,
                "is_safe": is_safe,
                "details": {"error": error_details, "safety_ratings": safety_ratings_info}
            })
    result = results
    return result
